import subprocess, json

# Gather observed data for mixing
def actual(hdr,f):
    args=["-L","-d,","-F",hdr,"-f",f]
    r=subprocess.run(["./executable"]+args, input=b"a,b,c,d,e\n1,2,3,4,5\n", capture_output=True)
    txt=r.stdout.decode().strip().split("\n")[0]
    return txt.split("\t") if txt else []

mp={"a":0,"b":1,"c":2,"d":3,"e":4}
inv={0:"a",1:"b",2:"c",3:"d",4:"e"}

observed=[]
fs=["1,2","2,1","1,3","3,1","1,5","5,1","2,5","5,2","2,4","4,2","3,5","5,3","1,2,3","3,2,1","1,5,2","2,1,5"]
hdrs=["a","b","c","d","e"]
for f in fs:
    for hdr in hdrs:
        out=actual(hdr,f)
        # map to indices
        indices=[mp[x] for x in out]
        observed.append((hdr,f,indices))

# Now try to hypothesize merging rules
def parse_f(f_str, ncols=5):
    indices=[]
    for part in f_str.split(","):
        part=part.strip()
        if not part:
            continue
        if "-" in part:
            if part.startswith("-"):
                lo=1; hi=int(part[1:])
            elif part.endswith("-"):
                lo=int(part[:-1]); hi=ncols
            else:
                a,b=part.split("-",1)
                lo=int(a); hi=int(b)
            for i in range(lo, hi+1):
                indices.append(i-1)
        else:
            indices.append(int(part)-1)
    # dedup like spec: keep first occurrence only
    seen=set()
    deduped=[]
    for x in indices:
        if x not in seen:
            deduped.append(x)
            seen.add(x)
    return deduped

def hdr_idx(hdr):
    return mp[hdr]

def predict(hdr,f,mode):
    hdr_i=hdr_idx(hdr)
    numeric=parse_f(f)
    if mode=="hdr_first_dedup":
        seen=set()
        out=[]
        for x in [hdr_i]:
            if x not in seen:
                out.append(x); seen.add(x)
        for x in numeric:
            if x not in seen:
                out.append(x); seen.add(x)
        return out
    if mode=="num_first_dedup":
        seen=set()
        out=[]
        for x in numeric:
            if x not in seen:
                out.append(x); seen.add(x)
        for x in [hdr_i]:
            if x not in seen:
                out.append(x); seen.add(x)
        return out
    if mode=="sorted":
        combined=[hdr_i]+numeric
        # dedup then sort
        seen=set()
        uniq=[]
        for x in combined:
            if x not in seen:
                uniq.append(x); seen.add(x)
        return sorted(uniq)
    if mode=="hdr_sorted_num_order":
        # header sorted? but we have single header
        return None
    if mode=="interleave_sorted":
        # maybe they merge two sorted lists? Not.
        pass
    return None

def test_mode(mode):
    mism=0
    for hdr,f,actual_idx in observed:
        pred=predict(hdr,f,mode)
        if pred is not None and pred!=actual_idx:
            mism+=1
    print(f"mode {mode} mismatches {mism}/{len(observed)}")
    # show examples
    for hdr,f,actual_idx in observed[:10]:
        pred=predict(hdr,f,mode)
        print(f" {hdr}+{f}: actual {actual_idx} pred {pred}")

for m in ["hdr_first_dedup","num_first_dedup","sorted"]:
    test_mode(m)
