#[derive(Debug, Clone)]
enum FieldSpec {
    Single(usize), // 1-based
    Range { low: Option<usize>, high: Option<usize> }, // None means open
}

fn parse_field_specs(s: &str) -> Result<Vec<FieldSpec>, String> {
    if s.is_empty() {
        return Err("Failed to parse field: ".into());
    }
    let mut specs = Vec::new();
    for part_raw in s.split(',') {
        let part = part_raw.trim_matches(|c| c == ' '); // but spec says spaces not allowed: "1, " gave error with space, so we should not trim; but field parsing should fail if part contains space.
        // Actually spec error for "1, " was Failed to parse field:  (single space). So part " " after split is considered failure.
        // We'll not trim, just use raw part.
        let part = part_raw;
        if part.is_empty() {
            return Err(format!("Failed to parse field: {}", part));
        }
        // check if part contains '-' 
        if part == "-" {
            return Err(format!("Failed to parse field: {}", part));
        }
        if let Some(dash_idx) = part.find('-') {
            let left = &part[..dash_idx];
            let right = &part[dash_idx+1..];
            // Ensure only one dash? Original allows "1-2,3-" etc but not "1-2-3". We can reject if right contains '-'
            if right.contains('-') {
                return Err(format!("Failed to parse field: {}", part));
            }
            // left empty means low None
            // right empty means high None
            let low_opt = if left.is_empty() {
                None
            } else {
                match left.parse::<usize>() {
                    Ok(v) => Some(v),
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            let high_opt = if right.is_empty() {
                None
            } else {
                match right.parse::<usize>() {
                    Ok(v) => Some(v),
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            // Check high < low when both Some
            if let (Some(lo), Some(hi)) = (low_opt, high_opt) {
                if hi < lo {
                    return Err(format!("High end of range less than low end of range: {}", part));
                }
            }
            specs.push(FieldSpec::Range { low: low_opt, high: high_opt });
        } else {
            // single
            match part.parse::<usize>() {
                Ok(v) => specs.push(FieldSpec::Single(v)),
                Err(_) => return Err(format!("Failed to parse field: {}", part)),
            }
        }
    }
    Ok(specs)
}

fn expand_field_specs(specs: &[FieldSpec], ncols: usize) -> Vec<usize> {
    let mut out = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for spec in specs {
        match spec {
            FieldSpec::Single(v) => {
                let idx = *v; // 1-based
                if idx == 0 { continue; } // though 0 would be invalid? But spec says 1-based, so 0 would be parsed but maybe not expected. Original may treat 0 as error? Not tested.
                // idx is 1-based, convert to 0-based ??? But we keep 0-based for selection, deduplicate.
                // We will produce 0-based indices later; for now we produce 1-based then dedup later? Let's use 0-based for convenience: *v -1 but need to handle dedup after conversion.
                // However dedup should be on 0-based indices.
                // But range expansion for open ends uses ncols.
                // We'll handle here.
                let zero = v - 1;
                // zero is 0-based
                // Duplicate handling: only add if not seen
                // Note: we need to consider that zero may be >= ncols => still consider for dedup but later per-line selection will produce out-of-range handling (skip or empty)
                // For dedup, we should track seen zero-based values that were actually within range? Original behavior for out-of-range fields: -f100 on 3 cols gave newline (empty) but also -f1,100 gave a\tb (so 100 skipped). Dedup still considers 100 as seen? For duplicate test, -f1,100,2 gave a\tb (duplicate not, but 100 not present). So seen should include even out-of-range indices to prevent duplicate effort? But original dedup was based on column index, irrespective of existence. So we track seen.
                if seen.insert(zero) {
                    out.push(zero);
                }
            },
            FieldSpec::Range { low, high } => {
                let lo = low.unwrap_or(1);
                let hi = high.unwrap_or(ncols); // if high None, use ncols
                // Note: ncols may be 0 for empty lines? Then hi =0 -> range empty.
                // If lo > ncols, then range empty (no elements)
                // Convert to zero-based iteration
                let start = lo;
                let end = hi;
                // Ensure start <= end (already checked)
                // Clip to ncols: only iterate up to ncols
                let clamped_end = std::cmp::min(end, ncols);
                for v in start..=clamped_end {
                    let zero = v - 1;
                    if seen.insert(zero) {
                        out.push(zero);
                    }
                }
                // For high == None (open to end), we already clamped to ncols, so includes up to ncols
                // For low == None case like "-5", lo=1 so we covered.
                // Need to handle case where ncols ==0: no push.
            }
        }
    }
    out
}

