#[derive(Debug, Clone)]
enum FieldSpec {
    Single(usize), // 1-based
    Range { low: Option<usize>, high: Option<usize> }, // None means open
}

fn parse_field_specs(s: &str) -> Result<Vec<FieldSpec>, String> {
    if s.is_empty() {
        return Err("Failed to parse field: ".into());
    }
    let mut specs = Vec::new();
    for part_raw in s.split(',') {
        let part = part_raw.trim_matches(|c| c == ' '); // but spec says spaces not allowed: "1, " gave error with space, so we should not trim; but field parsing should fail if part contains space.
        // Actually spec error for "1, " was Failed to parse field:  (single space). So part " " after split is considered failure.
        // We'll not trim, just use raw part.
        let part = part_raw;
        if part.is_empty() {
            return Err(format!("Failed to parse field: {}", part));
        }
        // check if part contains '-' 
        if part == "-" {
            return Err(format!("Failed to parse field: {}", part));
        }
        if let Some(dash_idx) = part.find('-') {
            let left = &part[..dash_idx];
            let right = &part[dash_idx+1..];
            // Ensure only one dash? Original allows "1-2,3-" etc but not "1-2-3". We can reject if right contains '-'
            if right.contains('-') {
                return Err(format!("Failed to parse field: {}", part));
            }
            // left empty means low None
            // right empty means high None
            let low_opt = if left.is_empty() {
                None
            } else {
                match left.parse::<usize>() {
                    Ok(v) => Some(v),
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            let high_opt = if right.is_empty() {
                None
            } else {
                match right.parse::<usize>() {
                    Ok(v) => Some(v),
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            // Check high < low when both Some
            if let (Some(lo), Some(hi)) = (low_opt, high_opt) {
                if hi < lo {
                    return Err(format!("High end of range less than low end of range: {}", part));
                }
            }
            specs.push(FieldSpec::Range { low: low_opt, high: high_opt });
        } else {
            // single
            match part.parse::<usize>() {
                Ok(v) => specs.push(FieldSpec::Single(v)),
                Err(_) => return Err(format!("Failed to parse field: {}", part)),
            }
        }
    }
    Ok(specs)
}

