    if let Err(e) = run(args) {
        log::error!("{}", e);
        process::exit(1);
    }
}

#[derive(Debug, Clone)]
enum FieldSpec {
    Single(usize),
    Range { low: Option<usize>, high: Option<usize> },
}

fn parse_field_specs(s: &str) -> Result<Vec<FieldSpec>, String> {
    if s.is_empty() {
        return Err("Failed to parse field: ".into());
    }
    let mut specs = Vec::new();
    for part_raw in s.split(',') {
        let part = part_raw;
        if part.is_empty() {
            return Err(format!("Failed to parse field: {}", part));
        }
        if part == "-" {
            return Err(format!("Failed to parse field: {}", part));
        }
        if let Some(dash_idx) = part.find('-') {
            let left = &part[..dash_idx];
            let right = &part[dash_idx+1..];
            if right.contains('-') {
                return Err(format!("Failed to parse field: {}", part));
            }
            let low_opt = if left.is_empty() {
                None
            } else {
                match left.parse::<usize>() {
                    Ok(v) => Some(v),
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            let high_opt = if right.is_empty() {
                None
            } else {
                match right.parse::<usize>() {
                    Ok(v) => Some(v),
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            if let (Some(lo), Some(hi)) = (low_opt, high_opt) {
                if hi < lo {
                    return Err(format!("High end of range less than low end of range: {}", part));
                }
            }
            // also check that low or high is not zero? 0 is technically allowed parse but fields are 1-based; original may treat 0 as valid? Not tested. We'll allow but later will handle.
            specs.push(FieldSpec::Range { low: low_opt, high: high_opt });
        } else {
            match part.parse::<usize>() {
                Ok(v) => specs.push(FieldSpec::Single(v)),
                Err(_) => return Err(format!("Failed to parse field: {}", part)),
            }
        }
    }
    Ok(specs)
}

fn expand_field_specs(specs: &[FieldSpec], ncols: usize, seen: &mut std::collections::HashSet<usize>, out: &mut Vec<usize>) {
    for spec in specs {
        match spec {
            FieldSpec::Single(v) => {
                if *v == 0 {
                    continue;
                }
                let idx = v - 1;
                if seen.insert(idx) {
                    out.push(idx);
                }
            },
            FieldSpec::Range { low, high } => {
                let lo = low.unwrap_or(1);
                let hi = high.unwrap_or(ncols);
                if lo == 0 {
                    continue;
                }
                if hi < lo {
                    continue;
                }
                let clamped_end = std::cmp::min(hi, ncols);
                if lo > clamped_end {
                    continue;
                }
                for v in lo..=clamped_end {
                    let idx = v - 1;
                    if seen.insert(idx) {
                        out.push(idx);
                    }
                }
            }
        }
    }
}

fn split_line_literal(line: &str, delim: &str) -> Vec<String> {
    if delim.is_empty() {
        // split into chars with leading/trailing empty
        let mut v = Vec::new();
        v.push(String::new());
        for ch in line.chars() {
            v.push(ch.to_string());
        }
        v.push(String::new());
        v
    } else if delim.len() == 1 {
        // single byte fast path: replicate panic when line starts with delim and we will later select field 0?
        // We do split normally but we will panic condition in caller when needed.
        line.split(delim).map(|s| s.to_string()).collect()
    } else {
        line.split(delim).map(|s| s.to_string()).collect()
    }
}

fn split_line_regex(line: &str, regex: &Regex) -> Vec<String> {
    // regex split, preserving empty leading/trailing as per regex behavior
    regex.split(line).map(|s| s.to_string()).collect()
}

fn run(args: Args) -> Result<(), String> {
    let is_literal = args.delim_is_literal;
    let delim_str = args.delimiter.clone();
    // effective output delimiter
    let effective_out_delim: String = if args.use_input_delim && is_literal {
        delim_str.clone()
    } else {
        args.output_delimiter.clone()
    };

    let field_specs = if let Some(ref s) = args.fields {
        Some(parse_field_specs(s)?)
    } else {
        None
    };
    let exclude_specs = if let Some(ref s) = args.exclude {
        Some(parse_field_specs(s)?)
    } else {
        None
    };

    let delim_regex: Option<Regex> = if !is_literal {
        match Regex::new(&delim_str) {
            Ok(r) => Some(r),
            Err(e) => return Err(format!("Invalid delimiter regex: {}", e)),
