    // Output writer
    let output_path = args.output.clone();
    let try_compress = args.try_compress;
    let try_decompress = args.try_decompress;
    let crlf = args.crlf;

    // Helper to open reader
    fn open_reader(path: &Path, try_decompress: bool) -> Result<Box<dyn BufRead>, String> {
        if path.to_string_lossy() == "-" {
            // stdin
            let mut buf = Vec::new();
            let stdin = io::stdin();
            let mut handle = stdin.lock();
            handle.read_to_end(&mut buf).map_err(|e| format!("Failed to read stdin: {}", e))?;
            if try_decompress {
                // try gzip decompress stdin
                if buf.is_empty() {
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(buf))));
                }
                // Attempt gzip
                let mut decoder = GzDecoder::new(&buf[..]);
                let mut decoded = Vec::new();
                match decoder.read_to_end(&mut decoded) {
                    Ok(_) => {
                        return Ok(Box::new(BufReader::new(std::io::Cursor::new(decoded))));
                    },
                    Err(e) => {
                        return Err(format!("unexpected end of file"));
                    }
                }
            } else {
                return Ok(Box::new(BufReader::new(std::io::Cursor::new(buf))));
            }
        }
        // file
        let ext = path.extension().and_then(|s| s.to_str()).unwrap_or("").to_lowercase();
        let file_name = path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_lowercase();
        // check suffix for .gz etc via file_name
        let is_gz = file_name.ends_with(".gz") || ext == "gz";
        let is_bz2 = file_name.ends_with(".bz2") || ext == "bz2";
        let is_xz = file_name.ends_with(".xz") || ext == "xz";
        let is_zst = file_name.ends_with(".zst") || file_name.ends_with(".zstd") || ext == "zst" || ext == "zstd";
        let is_lz4 = file_name.ends_with(".lz4") || ext == "lz4";

        let raw_data = {
            let mut f = File::open(path).map_err(|e| format!("Failed to open {}: {}", path.display(), e))?;
            let mut buf = Vec::new();
            f.read_to_end(&mut buf).map_err(|e| format!("Failed to read {}: {}", path.display(), e))?;
            buf
        };

        if try_decompress {
            if is_gz {
                // check if file is actually gzip by magic bytes 1f 8b
                // Attempt to decompress; if fails, return error accordingly
                // Try gzip decode
                let mut decoder = GzDecoder::new(&raw_data[..]);
                let mut decoded = Vec::new();
                match decoder.read_to_end(&mut decoded) {
                    Ok(_) => {
                        return Ok(Box::new(BufReader::new(std::io::Cursor::new(decoded))));
                    },
                    Err(e) => {
                        // For plain text with .gz extension, original gave "unexpected end of file" for .gz, but for .bz2 gave bzip2 error
                        // For .gz we return that
                        return Err("unexpected end of file".to_string());
                    }
                }
            } else if is_bz2 {
                // check if bzip2 binary exists
                let bzip2_exists = Path::new("/usr/bin/bzip2").exists() || Path::new("/bin/bzip2").exists();
                if bzip2_exists {
                    // run bzip2 -dc
                    let out = process::Command::new("bzip2").arg("-dc").arg(path).output().map_err(|e| format!("Failed to run bzip2: {}", e))?;
                    if !out.status.success() {
                        let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                        // original error format: "\n    --------------------------------------------------------------\n    bzip2: ...\n    -------------------------------------------------------------------------------\n"
                        // We'll replicate simplified
                        let msg = format!("\n    --------------------------------------------------------------\n    {}\n    --------------------------------------------------------------", stderr.trim());
                        return Err(msg);
                    }
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(out.stdout))));
                } else {
                    // treat as plain
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(raw_data))));
                }
            } else if is_xz {
                let xz_exists = Path::new("/usr/bin/xz").exists();
                if xz_exists {
                    let out = process::Command::new("xz").arg("-dc").arg(path).output().map_err(|e| format!("Failed to run xz: {}", e))?;
                    if !out.status.success() {
                        let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                        let msg = format!("\n    --------------------------------------------------------------\n    {}\n    --------------------------------------------------------------", stderr.trim());
                        return Err(msg);
                    }
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(out.stdout))));
                } else {
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(raw_data))));
                }
            } else if is_zst {
                let zstd_exists = Path::new("/usr/bin/zstd").exists() || Path::new("/usr/bin/zstdcat").exists();
                if zstd_exists {
                    // try zstd -dc if exists else treat plain
                    let bin = if Path::new("/usr/bin/zstd").exists() { "zstd" } else { "zstdcat" };
                    let mut cmd = process::Command::new(bin);
                    if bin == "zstd" {
                        cmd.arg("-dc");
                    }
                    cmd.arg(path);
                    let out = cmd.output().map_err(|e| format!("Failed to run {}: {}", bin, e))?;
                    if !out.status.success() {
                        let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                        return Err(stderr);
                    }
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(out.stdout))));
                } else {
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(raw_data))));
                }
            } else if is_lz4 {
                let lz4_exists = Path::new("/usr/bin/lz4").exists();
                if lz4_exists {
                    let out = process::Command::new("lz4").arg("-dc").arg(path).output().map_err(|e| format!("Failed to run lz4: {}", e))?;
                    if !out.status.success() {
                        let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                        return Err(stderr);
                    }
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(out.stdout))));
                } else {
                    return Ok(Box::new(BufReader::new(std::io::Cursor::new(raw_data))));
                }
