            // not try_decompress, but if file is gz content and we read it as plain, later when we try to split, the gzip bytes will be invalid? Original gave invalid data for gz file without -z (since reading gzip bytes as text and literal delimiter will cause missing newline? Actually gz file without -z gave invalid data error). So we just return raw.
            return Ok(Box::new(BufReader::new(std::io::Cursor::new(raw_data))));
        }
    }

    // We'll need to handle output
    let mut out_writer: Box<dyn Write> = if let Some(p) = output_path {
        let f = File::create(&p).map_err(|e| format!("Failed to create output file: {}", e))?;
        if try_compress {
            Box::new(GzEncoder::new(f, Compression::new(args.compression_level)))
        } else {
            Box::new(f)
        }
    } else {
        if try_compress {
            Box::new(GzEncoder::new(io::stdout(), Compression::new(args.compression_level)))
        } else {
            Box::new(io::stdout())
        }
    };

    let need_header = !args.header_field.is_empty() || !args.exclude_header.is_empty();
    let mut header_selected_indices: Vec<usize> = Vec::new();
    let mut exclude_header_indices: std::collections::HashSet<usize> = std::collections::HashSet::new();
    let mut header_ncols: Option<usize> = None;
    let mut header_line_raw: Option<String> = None;
    let mut first_file_lines: Vec<Vec<u8>> = Vec::new(); // we will store lines of first file to avoid re-reading after header peek
    let mut first_file_path: Option<PathBuf> = None;

    // We'll read files sequentially, but for header we need to peek first file's first line.
    // Approach: iterate input_paths, for each path open reader, read all lines into memory (Vec<Vec<u8>>), then process.
    // For first file that needs header, we will extract header.

    let mut all_inputs_data: Vec<(PathBuf, Vec<Vec<u8>>)> = Vec::new();
    for path in &input_paths {
        let mut reader = open_reader(path, try_decompress)?;
        let mut lines: Vec<Vec<u8>> = Vec::new();
        let mut buf = Vec::new();
