    let mut all_inputs_data: Vec<(PathBuf, Vec<Vec<u8>>)> = Vec::new();
    for path in &input_paths {
        let mut reader = open_reader(path, try_decompress)?;
        let mut lines: Vec<Vec<u8>> = Vec::new();
